using System;using System.IO;using System.Reflection;using System.Collections;using UnityEngine;using Bokumyaku.Presentation;using Bokumyaku.Simulation;
public static class EnemyBudCheck{
public static object Run(){var g=UnityEngine.Object.FindFirstObjectByType<BokumyakuGame>();if(!g.SavePath.Contains("ink-qa-"))throw new Exception("Isolated only");var flags=BindingFlags.Instance|BindingFlags.NonPublic;var kind=typeof(EnemyState).GetProperty("Kind");kind.SetValue(g.Run.Enemies[0],EnemyKind.Boss);kind.SetValue(g.Run.Enemies[1],EnemyKind.Splitter);var w=(InkBattleWorld)typeof(BokumyakuGame).GetField("battleWorld",flags).GetValue(g);w.Reset(g.Run);g.PresentBattle();var hud=UnityEngine.Object.FindFirstObjectByType<BokumyakuBattleHud>();typeof(BokumyakuBattleHud).GetField("extraOpen",flags).SetValue(hud,false);typeof(BokumyakuBattleHud).GetMethod("Refresh",flags).Invoke(hud,null);var entries=(IDictionary)typeof(InkBattleWorld).GetField("enemies",flags).GetValue(w);int models=0,buds=0;foreach(DictionaryEntry pair in entries){var e=pair.Value;var arr=(SpriteRenderer[])e.GetType().GetField("buds").GetValue(e);if(arr==null)continue;models++;if(arr.Length!=3)throw new Exception("Wrong bud count");foreach(var r in arr){if(!r.gameObject.activeSelf)throw new Exception("Hidden bud");buds++;}}if(models<2)throw new Exception("Missing fixture");ScreenCapture.CaptureScreenshot(Path.GetFullPath("../docs/evidence/enemy-bud-fixture.png"));var result=new{models,buds,passed=true,method="Isolated artificial boss/splitter kind fixture; not natural wave spawn test"};File.WriteAllText(Path.GetFullPath("../docs/evidence/enemy-bud-fixture.json"),Newtonsoft.Json.JsonConvert.SerializeObject(result));return result;}}
